-- Public model bindings are separate from private provider routing and billing.
create table public.ai_public_models (
 id text primary key, provider_model_id text not null unique,
 name text not null, family text not null, profile text not null, consumption text not null,
 recommended boolean not null default false, capabilities jsonb not null default '[]',
 enabled boolean not null default false, metadata jsonb not null default '{}',
 updated_at timestamptz not null default now()
);
alter table public.ai_public_models enable row level security;
revoke all on public.ai_public_models from public,anon,authenticated;
grant all on public.ai_public_models to service_role;
alter table public.ai_api_keys add column model_id text references public.ai_public_models(id);
