create function public.create_ai_project_with_model_key(p_org uuid,p_name text,p_hash text,p_prefix text,p_model text) returns uuid
language plpgsql security definer set search_path=public as $$
declare created_project uuid;
begin
 if not exists(select 1 from public.ai_public_models where id=p_model and enabled) then raise exception 'ai_model_unavailable'; end if;
 created_project:=public.create_ai_project_with_key(p_org,p_name,p_hash,p_prefix);
 update public.ai_api_keys set model_id=p_model where project_id=created_project;
 return created_project;
end $$;
revoke all on function public.create_ai_project_with_model_key(uuid,text,text,text,text) from public,anon,authenticated;
grant execute on function public.create_ai_project_with_model_key(uuid,text,text,text,text) to service_role;

-- Preserve existing pricing. New text models follow the established FX guardrail
-- (6 BRL/USD), markup (4) and 0.01 BRL per credit, with official standard prices.
do $migration$
declare cc uuid; feature uuid; mid uuid; item record; price record;
begin
 select id into cc from public.provider_cost_centers where provider='gemini';
 select id into feature from public.provider_features where cost_center_id=cc and feature_code='external_ai';
 if cc is null or feature is null then raise exception 'EXTERNAL_AI_BILLING_REQUIRED'; end if;
 for item in select * from (values
 ('gemini-3.5-flash',1.50::numeric,9.00::numeric,null::timestamptz),
 ('gemini-3.5-flash-lite',0.30::numeric,2.50::numeric,null::timestamptz),
 ('gemini-3.1-pro-preview',2.00::numeric,12.00::numeric,null::timestamptz),
 ('gemini-3.1-pro-preview-customtools',2.00::numeric,12.00::numeric,null::timestamptz),
 ('gemini-3.7-flash',0.75::numeric,3.75::numeric,'2027-01-01T00:00:00Z'::timestamptz),
 ('gemini-3.8-flash',0.75::numeric,3.75::numeric,'2027-01-01T00:00:00Z'::timestamptz)
 ) as model(name,input_usd,output_usd,expires) loop
 insert into public.provider_models(cost_center_id,provider_model_id,display_name,feature_code,supports_billing,enabled,input_unit,output_unit,metadata)
 values(cc,item.name,item.name,'external_ai',true,true,'input_token','output_token','{"external_ai_available":true,"verified_at":"2026-09-10"}')
 on conflict(cost_center_id,provider_model_id) do update set metadata=provider_models.metadata||excluded.metadata returning id into mid;
 for price in select * from (values ('input_token',item.input_usd),('output_token',item.output_usd)) as rate(unit,usd) loop
 insert into public.billing_rates(cost_center_id,feature_id,model_id,unit,provider_cost_per_unit,connecty_price_per_unit,margin_multiplier,minimum_charge_credits,currency,effective_from,effective_to,active,metadata)
 values(cc,feature,mid,price.unit::public.billing_unit,price.usd*6/1000000,price.usd*2400/1000000,4,1,'BRL',now(),item.expires,true,
 jsonb_build_object('pricing_source','https://ai.google.dev/gemini-api/docs/pricing','verified_at','2026-09-10','usd_fx_guardrail',6,'markup',4));
 if item.expires is not null then
 insert into public.billing_rates(cost_center_id,feature_id,model_id,unit,provider_cost_per_unit,connecty_price_per_unit,margin_multiplier,minimum_charge_credits,currency,effective_from,active,metadata)
 values(cc,feature,mid,price.unit::public.billing_unit,price.usd*12/1000000,price.usd*4800/1000000,4,1,'BRL',item.expires,true,
 jsonb_build_object('pricing_source','https://ai.google.dev/gemini-api/docs/pricing','verified_at','2026-09-10','usd_fx_guardrail',6,'markup',4));
 end if;
 end loop;
 end loop;
end $migration$;

