create function public.guard_ai_key_model() returns trigger language plpgsql set search_path=public as $$
begin
 if old.model_id is not null and new.model_id is distinct from old.model_id then raise exception 'ai_key_model_immutable'; end if;
 return new;
end $$;
create trigger ai_key_model_immutable before update of model_id on public.ai_api_keys for each row execute function public.guard_ai_key_model();

